export function RelatedPosts({
  heading = "{{heading}}",
  columns = "{{columns}}",
  showImage = {{showImage}},
  showExcerpt = {{showExcerpt}},
  accent = "{{accent}}",
}) {
  const posts = [
    { key: "growth", title: "Designing for scale", excerpt: "How we rebuilt our component library without breaking a single page.", seed: "growth" },
    { key: "onboard", title: "Onboarding that sticks", excerpt: "Three changes that cut our time-to-first-value in half.", seed: "onboard" },
    { key: "perf", title: "A year of performance work", excerpt: "What moved the needle, and what turned out to be a waste of time.", seed: "perf" },
  ];
  return (
    <section aria-labelledby="related-posts-r-heading" style={{ fontFamily: "system-ui, sans-serif", color: "#241430" }}>
      <h2 id="related-posts-r-heading" style={{ margin: "0 0 16px", fontSize: 20, fontWeight: 700 }}>{heading}</h2>
      <div style={{ display: "grid", gap: 20, gridTemplateColumns: `repeat(${columns}, 1fr)` }}>
        {posts.map((post) => (
          <article key={post.key} style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {showImage && (
              <img style={{ width: "100%", height: 140, objectFit: "cover", borderRadius: 10 }}
                src={`https://picsum.photos/seed/${post.seed}/320/180`} alt={`Illustration for ${post.title}`} />
            )}
            <h3 style={{ margin: 0, fontSize: 16, fontWeight: 600 }}>
              <a href="#" style={{ color: accent, textDecoration: "none" }}>{post.title}</a>
            </h3>
            {showExcerpt && <p style={{ margin: 0, fontSize: 14, color: "#241430cc" }}>{post.excerpt}</p>}
          </article>
        ))}
      </div>
    </section>
  );
}
